(async()=>{const f=document.createElement('iframe');f.src='/child-owned';const loaded=new Promise(r=>f.onload=r);document.body.append(f);await loaded;await new Promise(r=>setTimeout(r,30));const project=p=>p.getEntries().filter(e=>['navigation','resource'].includes(e.entryType)).map(e=>({type:e.entryType,name:new URL(e.name).pathname,initiator:e.initiatorType,responseEndPositive:e.responseEnd>0}));const early=f.contentWindow.earlyNavigation.slice();const late=f.contentWindow.performance.getEntriesByType('navigation').map(e=>e.entryType);const observer=new f.contentWindow.PerformanceObserver(list=>late.push(...list.getEntries().map(e=>e.entryType)));observer.observe({entryTypes:['navigation']});await new Promise(r=>setTimeout(r,30));return {parent:project(performance),child:project(f.contentWindow.performance),early,late}})()